using System.Security.Cryptography;
using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates inter-intra prediction on a 24-frame 128x128 aomenc two-pass clip encoded at a speed
/// setting that selects it: eligible single-reference blocks blend a DC/vertical/horizontal/smooth
/// intra prediction of the whole block over the motion-compensated samples, weighted by the
/// edge-faded inter-intra mask. Every displayed frame must be exactly equal to dav1d's output,
/// verified by per-frame SHA-256 digests.
/// </summary>
public class Av1InterIntraDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] FrameDigests = [
        "1d5ecb7509b1dfdc437f7e062a96e8928399fd3c6b733ec2b75bc0414bf272f3",
        "01a1970b36ad54fafc5ff784925d0cfbf87bceaf2cb1597a5254004252f8bfcb",
        "06191fcfaa8b26bd822473edbf98cc44d0762ec6608fa283c6479c91b322f6df",
        "eef5900339fee665be43de73bb3c75c783470efe74de00ab2e9a95385d6a0219",
        "fb8fde7004c28b38aafb1167e0396c71d53c30c592fc776899fcd00067ca5258",
        "12cb9099e8883a9d03c6f87a1dc4822a5aa0e390e96f9e462b5cb8002a6816c4",
        "b324c599dfff49fd22f9a3b92789bfe53fdca86f165220635f7d4da19c07fbc6",
        "91f8fa028193e80831f40f8a43eb98a91c6723b5ba1b4ba0da1cfd3921868f96",
        "86fd954d059bf20b1acffa686c91107ee941aff8cd215634e8c4006769a3b011",
        "a1117224536d00695ae8a91fed18a1021d6d8cf46996b84b6986f309b6d78c5e",
        "e9f03107c24534ffca1ff0b1a46f7b354717ab3449c33b98de786cd873e23608",
        "2ce5de9407ad8a7ca94d552bcf246e106b2d239e568abb684fbbf1309a61aee0",
        "a73da3e30add0277188ac77e688e2e07d8a4cfea50e1f3c604da32f1dbbf0ea6",
        "1dc046ae285edc3352ec9f428a90afb9853707915d2aa5701e401f95abd59456",
        "2a27996b115b4bd3ccf208a2aec1a9cf811187b41b058c7193fcf7f20901c472",
        "14183e54491a04f011cd806d4386d2ff0ce9f87615de2bffe93c059a9fd438b5",
        "6ac835cabf12fc167bf5f4f9be4ffe826b96f32eb2196d4c4f937ecb9041fc3d",
        "2ddb32ef001727ef93eeeef06ecfaff5eddc8348990a69285def734bff40aa21",
        "89965018e458d0c25711ff8a784329971b799ff60f3527cb26d6ae43e7844dea",
        "2ff6934d9a570695c6f2d3c2f18ed5a1740244a6aaaab47b748c8b20d033d09a",
        "6f969d85f5ea89c1e81ef34268fca4d220450a51ea30ca3cf47a0ce275f5201f",
        "8969b1f942d7a0bf2ea50fafd737ff1b44fe358a69ecca030d221502f258cd71",
        "5c411b547b6565c53f205b12c6fa452fad8aa5f9d36b1b4d9ffcd239daee989a",
        "7aea6d8f1337ce228ec1711c06fde9c60353645b987be680310d002ecdc74703",
    ];

    [Fact]
    public void DecodeDisplayFrames_InterIntraClip_MatchesDav1dExactly()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1DisplayFrame> frames = Av1DecoderCore.DecodeDisplayFrames(stream);

        Assert.Equal(FrameDigests.Length, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            using IncrementalHash hash = IncrementalHash.CreateHash(HashAlgorithmName.SHA256);
            AppendCropped(hash, frames[i].Luma);
            AppendCropped(hash, frames[i].ChromaU);
            AppendCropped(hash, frames[i].ChromaV);
            string digest = Convert.ToHexString(hash.GetHashAndReset()).ToLowerInvariant();
            Assert.True(FrameDigests[i] == digest, $"frame {i}: plane digest mismatch");
        }
    }

    private static void AppendCropped(IncrementalHash hash, Av1Plane plane)
    {
        for (int y = 0; y < plane.CropHeight; y++)
        {
            hash.AppendData(plane.Samples, y * plane.Width, plane.CropWidth);
        }
    }
}
